          "type": "single",
          "topic": "§ 5. «Травнева пісня»",
          "questionHtml": "<p>Яке зіставлення правильно порівнює оригінал і переклад «Травневої пісні». Чи вдалося, на вашу думку, перекладачеві Миколі Зерову відтворити радість юнацького почуття?</p>",
