          "type": "single",
          "topic": "§ 9. Романтизм як літературний напрям",
          "questionHtml": "<p>Яке твердження найточніше розкриває, у чому відмінність між раціоналістичним і романтичним світосприйманням?</p>",
          "options": [
            {
              "key": "А",
              "text": "Раціоналістичне світосприймання спирається передусім на розум, правила, але не логічне впорядкування світу."
            },
            {
              "key": "Б",
              "text": "У Франції просвітницькі гасла рівності й свободи намагалися здійснити під час Великої французької революції: було повалено монархію, проголошено республіку та скасовано станові привілеї."
            },
            {
              "key": "В",
              "text": "Раціоналістичне світосприймання спирається передусім на розум, правила й логічне впорядкування світу."
            },
            {
              "key": "Г",
              "text": "Це дискусійне завдання."
            }
          ],
          "correctKey": "В",
          "answerText": "Раціоналістичне світосприймання спирається передусім на розум, правила й логічне впорядкування світу. Романтичне надає перевагу почуттям, інтуїції, фантазії, внутрішньому життю та прагненню до ідеалу.",
          "optionSource": "prepared-v21-test",
