          "sourceCardId": "23.36",
          "type": "single",
          "topic": "§ 23. Роман «Джейн Ейр»",
          "questionHtml": "<p>Яке пояснення найточніше розкриває, чому образ Едварда Рочестера можна назвати байронічним?</p>",
